'use strict'


/**
 * Modules (Electron)
 * @constant
 */
const { app, Menu, shell, webContents } = require('electron')

/**
 * Modules (Third party)
 * @constant
 */
const isDebug = require('@sidneys/is-env')('debug')
const logger = require('@sidneys/logger')({ write: false })
const platformTools = require('@sidneys/platform-tools')

/**
 * Modules (Local)
 * @constant
 */
const appManifest = require('app/scripts/main-process/components/globals').appManifest


/**
 * Application
 * @constant
 * @default
 */
const appProductName = appManifest.productName
const appHomepage = appManifest.homepage


/** @namespace global **/
/** @namespace getAllWebContents **/

/**
 * App Menu Template
 * @function
 * @returns {Electron.MenuItemConstructorOptions[]}
 */
let getAppMenuTemplate = () => {
    let template = [
        {
            label: 'Edit',
            submenu: [
                {
                    label: 'Undo',
                    accelerator: 'CommandOrControl+Z',
                    role: 'undo'
                },
                {
                    label: 'Redo',
                    accelerator: 'Shift+CommandOrControl+Z',
                    role: 'redo'
                },
                {
                    type: 'separator'
                },
                {
                    label: 'Cut',
                    accelerator: 'CommandOrControl+X',
                    role: 'cut'
                },
                {
                    label: 'Copy',
                    accelerator: 'CommandOrControl+C',
                    role: 'copy'
                },
                {
                    label: 'Paste',
                    accelerator: 'CommandOrControl+V',
                    role: 'paste'
                },
                {
                    label: 'Select All',
                    accelerator: 'CommandOrControl+A',
                    role: 'selectall'
                }
            ]
        },
        {
            label: 'View',
            submenu: [
                {
                    label: 'Toggle Full Screen',
                    accelerator: (() => {
                        if (process.platform === 'darwin') {
                            return 'Ctrl+Command+F'
                        } else {
                            return 'F11'
                        }
                    })(),
                    click(item, focusedWindow) {
                        if (focusedWindow) {
                            focusedWindow.setFullScreen(!focusedWindow.isFullScreen())
                        }
                    }
                },
                {
                    type: 'separator'
                },
                {
                    label: 'Reset Zoom',
                    accelerator: 'CommandOrControl+0',
                    click() {
                        webContents.getAllWebContents().forEach((contents) => {
                            contents.send('zoom', 'reset')
                        })
                    }
                },
                {
                    label: 'Zoom In',
                    accelerator: 'CommandOrControl+Plus',
                    click() {
                        webContents.getAllWebContents().forEach((contents) => {
                            contents.send('zoom', 'in')
                        })
                    }
                },
                {
                    label: 'Zoom Out',
                    accelerator: 'CommandOrControl+-',
                    click() {
                        webContents.getAllWebContents().forEach((contents) => {
                            contents.send('zoom', 'out')
                        })
                    }
                },
                {
                    visible: isDebug,
                    type: 'separator'
                },
                {
                    label: 'Reload',
                    accelerator: 'CommandOrControl+R',
                    click(item, focusedWindow) {
                        if (focusedWindow) {
                            focusedWindow.reload()
                        }
                    }
                },
                {
                    label: 'Toggle Developer Tools',
                    accelerator: (() => {
                        return process.platform === 'darwin' ? 'Alt+Command+I' : 'Ctrl+Shift+I'
                    })(),
                    click(item, focusedWindow) {
                        if (focusedWindow) {
                            focusedWindow.toggleDevTools()
                        }
                    }
                }
            ]
        },
        {
            label: 'Window',
            role: 'window',
            submenu: [
                {
                    label: 'Minimize',
                    accelerator: 'CommandOrControl+M',
                    role: 'minimize'
                },
                {
                    label: 'Close',
                    accelerator: 'CommandOrControl+W',
                    role: 'close'
                }
            ]
        },
        {
            label: 'Help',
            role: 'help',
            submenu: [
                {
                    label: 'Learn More',
                    click() {
                        // Open URL
                        shell.openExternal(appHomepage)
                            .then((result) => {
                                logger.debug('AppMenu', 'shell.openExternal', 'result:', result)
                            })
                            .catch((error) => {
                                logger.error('AppMenu', 'shell.openExternal', error)
                            })
                    }
                }
            ]
        }
    ]

    if (platformTools.isMacOS) {
        template.unshift({
